begin;
create table if not exists public.arks_staff(email text primary key check(email=lower(email)),role text not null check(role in ('admin','finance','employee')),name text not null default '',active boolean not null default true);
alter table public.arks_staff enable row level security;
create function public.arks_role() returns text language sql stable security definer set search_path=public as $$ select role from public.arks_staff where email=lower(auth.jwt()->>'email') and active and (auth.jwt()->>'email_verified') is distinct from 'false' $$;
revoke all on function public.arks_role() from public;
grant execute on function public.arks_role() to authenticated;
create policy staff_read on public.arks_staff for select to authenticated using (email=lower(auth.jwt()->>'email') or public.arks_role() in ('admin','finance'));
create policy staff_manage on public.arks_staff for all to authenticated using(public.arks_role()='admin') with check(public.arks_role()='admin');
create table public.arks_companies(code text primary key,name text unique not null,details jsonb not null);
alter table public.arks_companies enable row level security;
create table public.arks_obligations(ref text primary key,entity text not null,owner_email text references public.arks_staff(email),data jsonb not null,updated_at timestamptz not null default now());
alter table public.arks_obligations enable row level security;
create table public.arks_documents(id uuid primary key default gen_random_uuid(),company text not null,obligation_ref text references public.arks_obligations(ref),name text not null,storage_path text unique not null,mime_type text not null,size_bytes bigint not null,uploaded_by uuid not null default auth.uid(),created_at timestamptz not null default now());
alter table public.arks_documents enable row level security;
create function public.arks_can_read_company(c text) returns boolean language sql stable security definer set search_path=public as $$ select public.arks_role() in ('admin','finance') or (public.arks_role()='employee' and exists(select 1 from public.arks_obligations where entity=c and owner_email=lower(auth.jwt()->>'email'))) $$;
revoke all on function public.arks_can_read_company(text) from public;
grant execute on function public.arks_can_read_company(text) to authenticated;
create policy company_read on public.arks_companies for select to authenticated using(public.arks_can_read_company(name));
create policy company_manage on public.arks_companies for all to authenticated using(public.arks_role() in ('admin','finance')) with check(public.arks_role() in ('admin','finance'));
create policy obligation_read on public.arks_obligations for select to authenticated using(public.arks_role() in ('admin','finance') or (public.arks_role()='employee' and owner_email=lower(auth.jwt()->>'email')));
create policy obligation_manage on public.arks_obligations for all to authenticated using(public.arks_role() in ('admin','finance')) with check(public.arks_role() in ('admin','finance'));
create function public.arks_update_task(task_ref text, task_status text, evidence text, comments text) returns void language plpgsql security definer set search_path=public as $$
begin
if task_status not in ('Not started','In progress','Submitted to authority','Completed','Not applicable') then raise exception 'Invalid status'; end if;
if task_status in ('Completed','Not applicable') and public.arks_role() not in ('admin','finance') then raise exception 'Finance must approve closure'; end if;
if task_status='Completed' and length(trim(evidence))=0 then raise exception 'Evidence required'; end if;
update public.arks_obligations set data=data || jsonb_build_object('status',task_status,'evidence',evidence,'comments',comments,'updatedBy',auth.jwt()->>'email','updatedOn',now()),updated_at=now() where ref=task_ref and (public.arks_role() in ('admin','finance') or (public.arks_role()='employee' and owner_email=lower(auth.jwt()->>'email')));
if not found then raise exception 'Task not found or permission denied'; end if;
end $$;
revoke all on function public.arks_update_task(text,text,text,text) from public;
grant execute on function public.arks_update_task(text,text,text,text) to authenticated;
create policy doc_read on public.arks_documents for select to authenticated using(public.arks_can_read_company(company));
create policy doc_insert on public.arks_documents for insert to authenticated with check(public.arks_can_read_company(company) and uploaded_by=auth.uid() and (storage.foldername(storage_path))[1]=auth.uid()::text and (storage.foldername(storage_path))[2]=company);
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('arks-documents','arks-documents',false,20971520,array['application/pdf','image/png','image/jpeg','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet']) on conflict(id) do nothing;
create policy arks_upload on storage.objects for insert to authenticated with check(bucket_id='arks-documents' and (storage.foldername(name))[1]=auth.uid()::text and public.arks_can_read_company((storage.foldername(name))[2]));
create policy arks_download on storage.objects for select to authenticated using(bucket_id='arks-documents' and public.arks_can_read_company((storage.foldername(name))[2]));
create table public.arks_email_log(id uuid primary key default gen_random_uuid(),obligation_ref text references public.arks_obligations(ref),recipient text not null,reminder_key text unique not null,status text not null default 'pending',provider_id text,created_at timestamptz not null default now());
alter table public.arks_email_log enable row level security;
create policy email_read on public.arks_email_log for select to authenticated using(public.arks_role() in ('admin','finance'));
grant select,insert,update,delete on public.arks_staff,public.arks_companies,public.arks_obligations to authenticated;
grant select,insert on public.arks_documents to authenticated;
grant select on public.arks_email_log to authenticated;
insert into public.arks_staff(email,role,name) values('ahmed@arks.ae','admin','Ahmed');
commit;
